var itemPath = kzbUrl.Substring(("kzb://" + projectNameInKzbFormat + "/").Length);
ProjectItem currentItem = project;

var parts = itemPath.Split('/').Where(x => !string.IsNullOrEmpty(x));
foreach (var part in parts)
